hl.bind("Print", hl.dsp.exec_cmd("hyprshot --clipboard-only -m region"))
hl.bind("SHIFT" .. " + Print", hl.dsp.exec_cmd("hyprshot -m window"))

hl.bind(mainMod .. " + G", hl.dsp.group.toggle())
hl.bind(mainModShift .. " + G", hl.dsp.window.move({ out_of_group = true }))
hl.bind(mainMod .. " + Tab", hl.dsp.group.next())
hl.bind(mainModShift .. " + Tab", hl.dsp.group.next({ forward = false }))
hl.bind(mainMod .. " + V", hl.dsp.exec_cmd("cliphist list| rofi -dmenu -display-columns 2| cliphist decode| wl-copy"))

-- Move/resize windows with mainMod + LMB/RMB and dragging

hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1.0 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { locked = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { locked = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl s 5%+"), { locked = true })
hl.bind(
	"XF86MonBrightnessDown",
	hl.dsp.exec_cmd(
		[[bash -c 'val=$(brightnessctl g); max=$(brightnessctl m); step=$((max/20)); min=$step; new=$((val-step)); [ $new -lt $min ] && new=$min; brightnessctl s $new']]
	),
	{ locked = true }
)

-- Limit it to 10%

-- Requires playerctl
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })
